/* --- les cin\xE9matiques --- */
function cineDuJeu(id){
  return (OPTS.cinematiques || []).filter(function(c){ return c && c.id === id; })[0] || null;
}
function dureeCine(id){ const c = cineDuJeu(id); return c ? c.duree : 0; }
let cineCours = null;
function jouerCine(id){
  const c = cineDuJeu(id);
  if(!c || cineCours) return;
  if(c.sceneId && GAME.scenes.some(function(s){ return s.id === c.sceneId; }) && (!current || current.id !== c.sceneId)){
    try{ loadScene(c.sceneId); }catch(e){}
    setTimeout(function(){ lancerCine(c); }, 450);
    return;
  }
  lancerCine(c);
}
function lancerCine(c){
  if(cineCours) return;
  const fond = mk('div', 'cine' + (c.bandes ? ' cine-bandes' : ''));
  fond.appendChild(mk('div', 'cine-bande cine-haut'));
  fond.appendChild(mk('div', 'cine-bande cine-bas'));
  const voile = mk('div', 'cine-voile');
  fond.appendChild(voile);
  const zone = mk('div', 'cine-textes');
  fond.appendChild(zone);
  let passer = null;
  if(c.passer){ passer = mk('button', 'cine-passer', 'Passer \u203A'); fond.appendChild(passer); }
  // un toucher pendant la cin\xE9matique ne traverse pas jusqu'\xE0 la sc\xE8ne
  fond.addEventListener('click', function(e){ e.stopPropagation(); });
  fond.addEventListener('pointerdown', function(e){ e.stopPropagation(); });
  document.getElementById('phone-frame').appendChild(fond);
  if(!c.interface) frameEl.classList.add('cine-en-cours');
  requestAnimationFrame(function(){ fond.classList.add('cine-on'); });
  const fov0 = camera.fov;
  const t0 = performance.now();
  const joues = {};
  const textes = (c.textes || []).map(function(x){ return { def: x, el: null }; });
  const cles = (c.cles || []).slice().sort(function(a, b){ return a.t - b.t; });
  const fondus = (c.fondus || []).slice().sort(function(a, b){ return a.t - b.t; });
  const depart = { t: 0, yaw: yaw, pitch: pitch, fov: fov0 };
  let fini = false;
  const finir = function(){
    if(fini) return;
    fini = true; cineCours = null;
    if(Math.abs(camera.fov - fov0) > 0.01){ camera.fov = fov0; camera.updateProjectionMatrix(); }
    fond.classList.remove('cine-on');
    frameEl.classList.remove('cine-en-cours');
    textes.forEach(function(x){ if(x.el) x.el.classList.remove('on'); });
    setTimeout(function(){ if(fond.parentNode) fond.parentNode.removeChild(fond); }, 450);
    needsRedraw();
  };
  if(passer) passer.addEventListener('click', function(e){ e.stopPropagation(); finir(); });
  cineCours = { c: c, finir: finir };
  animsCamera.push(function(t){
    if(fini) return true;
    const s = (t - t0) / 1000;
    if(cles.length){
      let a = depart, b = null;
      for(let i = 0; i < cles.length; i++){
        if(cles[i].t <= s) a = cles[i];
        else { b = cles[i]; break; }
      }
      let f;
      if(b){
        const k = b.t > a.t ? Math.max(0, Math.min(1, (s - a.t) / (b.t - a.t))) : 1;
        const e = adoucir(k);
        let dy = b.yaw - a.yaw; dy = Math.atan2(Math.sin(dy), Math.cos(dy));
        yaw = a.yaw + dy * e; pitch = a.pitch + (b.pitch - a.pitch) * e;
        f = a.fov + (b.fov - a.fov) * e;
      } else { yaw = a.yaw; pitch = a.pitch; f = a.fov; }
      if(Math.abs(camera.fov - f) > 0.01){ camera.fov = f; camera.updateProjectionMatrix(); }
      needsRedraw();
    }
    textes.forEach(function(x){
      const d = x.def, dedans = s >= d.t && s < d.t + d.d;
      if(dedans && !x.el){
        const el = mk('div', 'cine-texte ct-' + d.place, trJeu(d.texte));
        x.el = el; zone.appendChild(el);
        requestAnimationFrame(function(){ el.classList.add('on'); });
      } else if(!dedans && x.el){
        const el = x.el; x.el = null;
        el.classList.remove('on');
        setTimeout(function(){ if(el.parentNode) el.parentNode.removeChild(el); }, 450);
      }
    });
    (c.sons || []).forEach(function(x, i){
      if(joues[i] || s < x.t || !x.soundId) return;
      joues[i] = 1;
      try{ playSoundEffects([{ kind: 'sound', soundId: x.soundId, volume: x.volume }]); }catch(e){}
    });
    let op = 0, coul = 'noir';
    fondus.forEach(function(f){
      if(s >= f.t + f.d){ op = f.sens === 'ferme' ? 1 : 0; coul = f.couleur; }
      else if(s >= f.t){ const p = (s - f.t) / f.d; op = f.sens === 'ferme' ? p : 1 - p; coul = f.couleur; }
    });
    voile.style.opacity = String(op);
    voile.style.background = coul === 'blanc' ? '#fff' : '#000';
    if(s >= c.duree){ finir(); return true; }
    return false;
  });
  needsRedraw();
}
// La cin\xE9matique d'ouverture : d\xE8s que la nouvelle partie est \xE0 l'\xE9cran.
function introCine(){
  if(!OPTS.introCine || !cineDuJeu(OPTS.introCine)) return;
  let n = 0;
  const essai = function(){
    n++;
    if(playerScreen === 'playing'){ jouerCine(OPTS.introCine); return; }
    if(n < 40) setTimeout(essai, 150);
  };
  setTimeout(essai, 300);
}
if(CINE_TEST) setTimeout(function(){ jouerCine(CINE_TEST); }, 700);
// Ce qui se joue juste apr\xE8s \xAB Nouvelle partie \xBB : la cin\xE9matique
// d'ouverture, puis la suite d'actions choisie dans l'\xE9diteur.
// Comme une page de livre-jeu : chaque morceau attend que le joueur ait
// ferm\xE9 le texte, fini le dialogue ou vu la cin\xE9matique avant la suite.
let lancementAttente = false;
function lancementLibre(){
  const m = document.getElementById('modal');
  return playerScreen === 'playing' && !cineCours && !(m && m.style.display === 'flex') && !avOuvert();
}
function lancementSuite(liste, n){
  if(!liste.length) return;
  if(!lancementLibre()){ if((n || 0) < 2400) setTimeout(function(){ lancementSuite(liste, (n || 0) + 1); }, 150); return; }
  let k = -1;
  for(let i = 0; i < liste.length; i++){
    const a = liste[i];
    if(a && (a.type === 'attendre' || (a.type === 'cinematique' && a.attendre !== false && i < liste.length - 1))){ k = i; break; }
  }
  const enCine = k >= 0 && liste[k].type === 'cinematique';
  const eff = runActionsNow(k < 0 ? liste : liste.slice(0, enCine ? k + 1 : k));
  const msg = eff.filter(function(x){ return x.kind === 'text'; }).pop();
  if(msg) showModal(msg.text);
  const d = pickDialogue(eff);
  if(d) openDialogue(d);
  const nav = pickNavigate(eff, null);
  if(nav && (!current || nav !== current.id)) loadScene(nav);
  if(k < 0) return;
  const reste = liste.slice(k + 1);
  if(enCine){ setTimeout(function(){ lancementSuite(reste, 0); }, 600); return; }
  // la pause commence quand le joueur a fini de lire ce qui pr\xE9c\xE8de
  const ms = Math.round((liste[k].secondes || 1) * 1000);
  let p = 0;
  const pause = function(){
    p++;
    if(!lancementLibre() && p < 2400){ setTimeout(pause, 150); return; }
    setTimeout(function(){ lancementSuite(reste, 0); }, ms);
  };
  setTimeout(pause, 200);
}
function lancementPartie(){
  const intro = OPTS.introCine && cineDuJeu(OPTS.introCine) ? [{ type: 'cinematique', cineId: OPTS.introCine, attendre: true }] : [];
  const tout = intro.concat(normalizeActions(OPTS.lancement || []));
  if(tout.length) setTimeout(function(){ lancementSuite(tout, 0); }, 250);
}
if(LANCEMENT_TEST) setTimeout(lancementPartie, 500);
/* ================================================================== */
/*  Lot 41 : livre-jeu (paragraphes, feuille d\u2019aventure, mots-codes,   */
/*  cartes du destin, marque-pages, voix int\xE9rieures), enqu\xEAte         */
/*  (examiner, photo-preuve, d\xE9duction), pile de la lampe, et le fil   */
/*  de l'histoire pendant les tests.                                   */
/*  Pas d'accent grave ni de barre oblique inverse : ce code vit dans  */
/*  une cha\xEEne du moteur.                                              */
/* ================================================================== */
function av41(){ return (OPTS && OPTS.l41) || {}; }
function avListe(k){ const l = av41()[k]; return Array.isArray(l) ? l : []; }
function avTrouve(k, id){ return avListe(k).filter(function(x){ return x.id === id; })[0] || null; }
const AV_NL = String.fromCharCode(10);
function avDes(formule){
  const t = String(formule == null ? '' : formule).toLowerCase().split(' ').join('');
  if(!t) return 0;
  const morceaux = [];
  let cur = '', signe = 1;
  for(let k = 0; k < t.length; k++){
    const ch = t[k];
    if(ch === '+' || ch === '-'){ if(cur) morceaux.push([signe, cur]); signe = ch === '-' ? -1 : 1; cur = ''; }
    else cur += ch;
  }
  if(cur) morceaux.push([signe, cur]);
  let total = 0;
  morceaux.forEach(function(m){
    const p = m[1].split('d');
    if(p.length === 2){
      const n = Math.min(50, parseInt(p[0], 10) || 1), f = parseInt(p[1], 10) || 6;
      for(let j = 0; j < n; j++) total += m[0] * (1 + Math.floor(Math.random() * f));
    } else total += m[0] * (parseFloat(p[0]) || 0);
  });
  return total;
}
function avStats(){ const f = av41().feuille || {}; return Array.isArray(f.stats) ? f.stats.filter(function(s){ return s && s.id; }) : []; }
// Les caract\xE9ristiques se tirent la premi\xE8re fois qu'on en a besoin dans une partie.
function avInit(){
  avStats().forEach(function(s){
    const k = 'car_' + s.id;
    if(!vars['__tire:' + s.id]){ const v = avDes(s.depart || '0'); vars[k] = v; vars[k + '_max'] = v; vars['__tire:' + s.id] = 1; }
  });
  const pile = av41().pile || {};
  if(pile.active && vars.__pile == null) vars.__pile = Math.max(1, parseFloat(pile.duree) || 120);
}
function avStyleDe(id){
  const l = avListe('styles');
  const s = l.filter(function(x){ return x.id === id; })[0] || l[0] || {};
  return { papier: s.papier || '#f3ead6', encre: s.encre || '#2a2118', accent: s.accent || '#8a3b12', police: s.police || 'Georgia, serif', fond: s.fond || '', arrondi: s.arrondi == null ? 14 : s.arrondi };
}
let avCssFait = false;
function avCss(){
  if(avCssFait) return; avCssFait = true;
  const st = document.createElement('style');
  st.textContent = [
    '.av41-fond{position:absolute;inset:0;z-index:940;display:flex;align-items:center;justify-content:center;background:rgba(5,6,10,.62);animation:av41in .22s ease-out}',
    '.av41-fond.av41-libre{background:transparent;pointer-events:none}',
    '@keyframes av41in{from{opacity:0}to{opacity:1}}',
    '.av41-boite{box-sizing:border-box;width:min(560px,92%);max-height:88%;overflow-y:auto;padding:22px 22px 18px;box-shadow:0 18px 50px rgba(0,0,0,.55);position:relative}',
    '.av41-boite h2{margin:0 0 10px;font-size:1.35em;font-weight:600}',
    '.av41-boite p{margin:0 0 10px;line-height:1.55}',
    '.av41-num{opacity:.6;font-size:.8em;letter-spacing:.08em;text-transform:uppercase;display:block;margin-bottom:2px}',
    '.av41-img{display:block;max-width:100%;max-height:240px;margin:0 auto 12px;border-radius:8px}',
    '.av41-choix{display:block;width:100%;text-align:left;margin-top:8px;padding:12px 14px;min-height:46px;font:inherit;border-radius:10px;cursor:pointer;border:1.5px solid currentColor;background:transparent;color:inherit}',
    '.av41-choix[disabled]{opacity:.42;cursor:not-allowed}',
    '.av41-choix:not([disabled]):active{transform:scale(.99)}',
    '.av41-bouton{display:inline-block;margin:10px 8px 0 0;padding:10px 16px;min-height:44px;font:inherit;border-radius:10px;cursor:pointer;border:none}',
    '.av41-chrono{height:5px;border-radius:3px;margin:4px 0 6px;transform-origin:left;transition:transform linear}',
    '.av41-carte{width:min(300px,78%);aspect-ratio:2/3;perspective:900px}',
    '.av41-carte-in{position:relative;width:100%;height:100%;transition:transform .7s ease;transform-style:preserve-3d}',
    '.av41-carte.vue .av41-carte-in{transform:rotateY(180deg)}',
    '.av41-face{position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;border-radius:16px;box-sizing:border-box;padding:16px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;box-shadow:0 14px 40px rgba(0,0,0,.6)}',
    '.av41-dos{background:repeating-linear-gradient(45deg,#3a2414 0 10px,#4a2f1a 10px 20px);border:6px solid #c9a86a}',
    '.av41-recto{transform:rotateY(180deg)}',
    '.av41-recto img{max-width:100%;max-height:45%;border-radius:8px;margin-bottom:10px}',
    '.av41-toast{position:absolute;left:50%;top:14%;transform:translateX(-50%);z-index:960;background:rgba(16,18,26,.92);color:#fff;padding:12px 18px;border-radius:14px;font:15px/1.4 system-ui,sans-serif;text-align:center;max-width:84%;pointer-events:none;animation:av41in .2s ease-out;transition:opacity .4s}',
    '.av41-pensee{position:absolute;left:50%;top:9%;transform:translateX(-50%);z-index:965;max-width:80%;padding:12px 18px;border-radius:18px;background:rgba(20,16,40,.9);color:#efe7ff;font:italic 16px/1.45 Georgia,serif;box-shadow:0 8px 30px rgba(0,0,0,.5);pointer-events:none;transition:opacity .5s}',
    '.av41-pensee b{display:block;font-style:normal;font:600 11px/1.2 system-ui,sans-serif;letter-spacing:.12em;text-transform:uppercase;color:#b9a4ff;margin-bottom:4px}',
    '.av41-examen{position:relative;width:min(640px,94%);height:min(480px,62vh);overflow:hidden;touch-action:none;border-radius:12px;background:#0d0f14}',
    '.av41-examen img{position:absolute;left:50%;top:50%;max-width:86%;max-height:86%;transform-origin:center;user-select:none;-webkit-user-drag:none}',
    '.av41-outils{display:flex;gap:8px;justify-content:center;margin-top:10px;flex-wrap:wrap}',
    '.av41-outils button{min-width:46px;min-height:44px;border-radius:10px;border:none;background:#2a2f3c;color:#fff;font:16px system-ui,sans-serif;cursor:pointer;padding:0 12px}',
    '.av41-viseur{position:absolute;left:18%;right:18%;top:18%;bottom:18%;border:2px solid rgba(255,255,255,.85);border-radius:6px;box-shadow:0 0 0 2000px rgba(0,0,0,.25)}',
    '.av41-viseur:after{content:"";position:absolute;left:50%;top:50%;width:18px;height:18px;margin:-9px 0 0 -9px;border:2px solid #fff;border-radius:50%}',
    '.av41-declic{position:absolute;left:50%;bottom:26px;transform:translateX(-50%);width:74px;height:74px;border-radius:50%;border:5px solid #fff;background:rgba(255,255,255,.25);pointer-events:auto;cursor:pointer}',
    '.av41-annuler{position:absolute;right:18px;bottom:40px;pointer-events:auto;min-height:44px;padding:0 16px;border-radius:12px;border:none;background:rgba(0,0,0,.6);color:#fff;font:15px system-ui,sans-serif;cursor:pointer}',
    '.av41-flash{position:absolute;inset:0;background:#fff;z-index:970;pointer-events:none;animation:av41flash .45s ease-out forwards}',
    '@keyframes av41flash{from{opacity:.95}to{opacity:0}}',
    '.av41-trou{font:inherit;padding:6px 8px;margin:0 4px;border-radius:8px;border:1.5px solid currentColor;background:rgba(255,255,255,.55);color:inherit;max-width:46%}',
    '.av41-feuille-btn{position:absolute;left:12px;bottom:12px;z-index:930;width:52px;height:52px;border-radius:26px;border:none;background:rgba(16,18,26,.8);color:#fff;font-size:24px;cursor:pointer}',
    '.av41-ligne{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid rgba(0,0,0,.12)}',
    '.av41-fil{position:absolute;right:8px;bottom:8px;z-index:990;width:290px;max-width:70%;max-height:46%;overflow:auto;background:rgba(10,12,18,.9);color:#dfe6f0;font:12px/1.35 system-ui,sans-serif;border-radius:10px;padding:6px 8px;box-shadow:0 6px 24px rgba(0,0,0,.5)}',
    '.av41-fil button{background:#2c3446;color:#fff;border:none;border-radius:6px;padding:3px 7px;cursor:pointer;font:12px system-ui,sans-serif}',
    '.av41-fil .av41-f-entree{border-top:1px solid rgba(255,255,255,.1);padding:4px 0;display:flex;gap:6px;align-items:flex-start}'
  ].join(AV_NL);
  document.head.appendChild(st);
}
function avCadre(){ return document.getElementById('phone-frame') || document.body; }
function avToast(t, ms){
  avCss();
  const d = mk('div', 'av41-toast', t);
  avCadre().appendChild(d);
  setTimeout(function(){ d.style.opacity = '0'; }, ms || 2200);
  setTimeout(function(){ if(d.parentNode) d.remove(); }, (ms || 2200) + 500);
}
function avOuvert(){ return !!document.querySelector('.av41-fond'); }
function avQuandLibre(fn, n){
  const m = document.getElementById('modal');
  const libre = playerScreen === 'playing' && !cineCours && !(m && m.style.display === 'flex') && !avOuvert();
  if(libre){ fn(); return; }
  if((n || 0) < 2400) setTimeout(function(){ avQuandLibre(fn, (n || 0) + 1); }, 150);
}
function avJouer(liste){ const l = normalizeActions(liste || []); if(l.length) lancementSuite(l, 0); }
// Une fen\xEAtre du livre : papier, encre et police du style choisi.
function avFenetre(styleId, libre){
  avCss();
  const fond = mk('div', 'av41-fond' + (libre ? ' av41-libre' : ''));
  fond.addEventListener('click', function(e){ e.stopPropagation(); });
  fond.addEventListener('pointerdown', function(e){ e.stopPropagation(); });
  const st = avStyleDe(styleId);
  const box = mk('div', 'av41-boite');
  box.style.background = st.fond ? 'url("' + st.fond + '") center/cover, ' + st.papier : st.papier;
  box.style.color = st.encre;
  box.style.fontFamily = st.police;
  box.style.borderRadius = st.arrondi + 'px';
  if(!libre) fond.appendChild(box);
  avCadre().appendChild(fond);
  const fermer = function(){ if(fond.parentNode) fond.remove(); try{ hudSync(); }catch(e){} };
  return { fond: fond, box: box, st: st, fermer: fermer };
}
function avBouton(f, texte, onclick, plein){
  const b = mk('button', 'av41-bouton', texte); b.type = 'button';
  b.style.background = plein === false ? 'transparent' : f.st.accent;
  b.style.color = plein === false ? f.st.encre : '#fff';
  if(plein === false) b.style.border = '1.5px solid ' + f.st.encre;
  b.onclick = function(e){ e.stopPropagation(); onclick(); };
  f.box.appendChild(b);
  return b;
}
function avParagraphes(texte, box){
  String(texte || '').split(AV_NL + AV_NL).forEach(function(bloc){
    if(!bloc.trim()) return;
    const p = mk('p', '');
    bloc.split(AV_NL).forEach(function(l, i){ if(i) p.appendChild(document.createElement('br')); p.appendChild(document.createTextNode(trJeu(l))); });
    box.appendChild(p);
  });
}

/* --- conditions des choix --- */
function avSi(si){
  if(!si || !si.type) return true;
  if(si.type === 'mot') return !!vars['mot_' + si.mot];
  if(si.type === 'sansmot') return !vars['mot_' + si.mot];
  if(si.type === 'stat') return (parseFloat(vars['car_' + si.stat]) || 0) >= (parseFloat(si.min) || 0);
  if(si.type === 'objet') return (inventory[si.itemId] || 0) > 0;
  if(si.type === 'vu') return !!vars['__para:' + si.num];
  return true;
}
function avSiTexte(si){
  if(!si || !si.type) return '';
  if(si.type === 'mot') return 'Il te faut le mot-code ' + String(si.mot || '').toUpperCase();
  if(si.type === 'stat'){ const s = avStats().filter(function(x){ return x.id === si.stat; })[0]; return 'Il te faut ' + (s ? s.nom : si.stat) + ' ' + (si.min || 0); }
  if(si.type === 'objet'){ const it = (GAME.items || []).filter(function(x){ return x.id === si.itemId; })[0]; return 'Il te faut : ' + (it ? it.name : 'un objet'); }
  return '';
}

/* --- une page du livre --- */
let avParaOuvert = null;
function avPage(num){
  const p = avListe('paragraphes').filter(function(x){ return String(x.num) === String(num); })[0];
  if(!p){ avToast('Paragraphe ' + num + ' introuvable'); return; }
  avInit();
  vars['__para:' + p.num] = 1; vars.__para = p.num;
  avParaOuvert = p.num;
  if(p.actions && p.actions.length){ try{ runActionsNow(normalizeActions(p.actions)); }catch(e){} }
  if(!avParaOuvert || avParaOuvert !== p.num) return;
  if(document.querySelector('.av41-mort')) return;
  const f = avFenetre(p.style);
  f.fond.setAttribute('data-av41-page', String(p.num));
  const h = mk('h2', '');
  h.appendChild(mk('span', 'av41-num', '\xA7 ' + p.num));
  if(p.titre) h.appendChild(document.createTextNode(trJeu(p.titre)));
  h.style.color = f.st.accent;
  f.box.appendChild(h);
  if(p.image){ const im = document.createElement('img'); im.className = 'av41-img'; im.src = p.image; im.alt = ''; f.box.appendChild(im); }
  avParagraphes(p.texte, f.box);
  const choix = (p.choix || []).filter(function(c){ return c && (avSi(c.si) || !c.cacher); });
  const partir = function(c){
    if(f.fond._fini) return; f.fond._fini = true;
    if(f.fond._chrono) clearTimeout(f.fond._chrono);
    f.fermer(); avParaOuvert = null;
    try{ if(c.texte) rejChoix(c.texte); }catch(e){}
    const suite = (c.actions || []).slice();
    if(c.vers !== '' && c.vers != null) suite.push({ type: 'av_paragraphe', num: String(c.vers) });
    avJouer(suite);
  };
  const boutons = [];
  choix.forEach(function(c){
    const b = mk('button', 'av41-choix', trJeu(c.texte || 'Continuer')); b.type = 'button';
    b.setAttribute('data-av41-choix', c.vers == null ? '' : String(c.vers));
    if(!avSi(c.si)){ b.disabled = true; b.title = avSiTexte(c.si); b.textContent = '\u{1F512} ' + b.textContent; }
    b.onclick = function(e){ e.stopPropagation(); partir(c); };
    f.box.appendChild(b);
    boutons.push({ b: b, c: c });
  });
  if(!choix.length){
    if(p.fin === 'victoire') avBouton(f, 'Fin', function(){ f.fermer(); avParaOuvert = null; try{ montrerFin({ titre: p.titre || 'Fin', texte: '' }); }catch(e){} });
    else if(p.fin === 'defaite') avBouton(f, 'Continuer', function(){ f.fermer(); avParaOuvert = null; avMort({ titre: p.titre || 'Ton aventure s\u2019arr\xEAte ici', texte: '' }); });
    else avBouton(f, 'Continuer', function(){ f.fermer(); avParaOuvert = null; });
  }
  const sec = parseFloat(p.chrono) || 0;
  const actifs = boutons.filter(function(x){ return !x.b.disabled; });
  if(sec > 0 && actifs.length){
    const barre = mk('div', 'av41-chrono'); barre.style.background = f.st.accent;
    f.box.insertBefore(barre, boutons[0].b);
    requestAnimationFrame(function(){ requestAnimationFrame(function(){ barre.style.transitionDuration = sec + 's'; barre.style.transform = 'scaleX(0)'; }); });
    const i = Math.max(0, Math.min(actifs.length - 1, parseInt(p.defaut, 10) || 0));
    f.fond._chrono = setTimeout(function(){ partir(actifs[i].c); }, sec * 1000);
  }
}

/* --- feuille d\u2019aventure --- */
function avFeuille(){
  avInit();
  const fe = av41().feuille || {};
  const f = avFenetre(fe.style);
  f.fond.setAttribute('data-av41-feuille', '1');
  const h = mk('h2', '', trJeu(fe.titre || 'Feuille d\u2019aventure')); h.style.color = f.st.accent; f.box.appendChild(h);
  avStats().forEach(function(s){
    const l = mk('div', 'av41-ligne');
    l.appendChild(mk('span', '', trJeu(s.nom || s.id)));
    const v = vars['car_' + s.id], mx = vars['car_' + s.id + '_max'];
    l.appendChild(mk('b', '', String(v == null ? '-' : v) + (s.max && mx != null ? ' / ' + mx : '')));
    f.box.appendChild(l);
  });
  if(av41().pile && av41().pile.active){ const l = mk('div', 'av41-ligne'); l.appendChild(mk('span', '', '\u{1F526} Pile')); l.appendChild(mk('b', '', Math.max(0, Math.round(parseFloat(vars.__pile) || 0)) + ' s')); f.box.appendChild(l); }
  const mots = (GAME.variables || []).filter(function(v){ return v && String(v.key).indexOf('mot_') === 0 && vars[v.key]; });
  if(mots.length){ f.box.appendChild(mk('h3', '', 'Mots-codes')); const p = mk('p', '', mots.map(function(v){ return String(v.label || v.key.slice(4)).toUpperCase(); }).join(' \xB7 ')); f.box.appendChild(p); }
  const album = Array.isArray(vars.__album) ? vars.__album : [];
  if(album.length){ f.box.appendChild(mk('h3', '', 'Photos')); f.box.appendChild(mk('p', '', album.map(function(a){ return '\u{1F4F7} ' + a; }).join(AV_NL))); }
  const journal = Array.isArray(vars.__parcours) ? vars.__parcours : [];
  if(journal.length){
    f.box.appendChild(mk('h3', '', 'Journal'));
    journal.slice(-30).forEach(function(t){ f.box.appendChild(mk('p', '', '\u2022 ' + t)); });
  }
  avBouton(f, 'Fermer', f.fermer);
}
function avFeuilleBouton(){
  const fe = av41().feuille || {};
  let b = document.querySelector('.av41-feuille-btn');
  const montrer = !!fe.bouton && avStats().length > 0 && playerScreen === 'playing' && !cineCours;
  if(!montrer){ if(b) b.style.display = 'none'; return; }
  if(!b){ avCss(); b = mk('button', 'av41-feuille-btn', '\u{1F4DC}'); b.type = 'button'; b.setAttribute('aria-label', 'Feuille d\u2019aventure'); b.setAttribute('data-av41-feuille-btn', '1'); b.onclick = function(e){ e.stopPropagation(); if(!avOuvert()) avFeuille(); }; avCadre().appendChild(b); }
  b.style.display = 'block';
}

/* --- d\xE9s --- */
function avDesMontre(r, a){
  if(!r) return;
  const s = avStats().filter(function(x){ return x.id === a.stat; })[0];
  const nom = s ? s.nom : 'Caract\xE9ristique';
  avToast('\u{1F3B2} ' + r.total + (a.sens === 'plus' ? ' \u2265 ' : ' \u2264 ') + r.cible + ' (' + nom + ')' + AV_NL + (r.ok ? (a.ok || 'R\xE9ussi !') : (a.rate || 'Rat\xE9\u2026')), 2600);
}

/* --- marque-page et mort --- */
function avEtat(){
  const v = {}; Object.keys(vars).forEach(function(k){ if(k !== '__marque') v[k] = vars[k]; });
  return JSON.stringify({ inventory: inventory, vars: v, discovered: Array.from(discovered), scene: current ? current.id : '', para: avParaOuvert });
}
function avRestaure(txt){
  let s = null; try{ s = JSON.parse(txt); }catch(e){ return false; }
  if(!s) return false;
  const marque = vars.__marque;
  inventory = s.inventory || {};
  vars = s.vars || {};
  if(marque) vars.__marque = marque;
  discovered = new Set(s.discovered || []);
  if(s.scene && GAME.scenes.some(function(x){ return x.id === s.scene; }) && (!current || current.id !== s.scene)) loadScene(s.scene);
  try{ renderHotspots(); hudSync(); saveGame(); }catch(e){}
  if(s.para) setTimeout(function(){ avQuandLibre(function(){ avPage(s.para); }); }, 500);
  return true;
}
function avMarque(a){
  vars.__marque = avEtat();
  if(!a || a.annoncer !== false) avToast('\u{1F516} ' + trJeu((a && a.texte) || 'Marque-page pos\xE9'));
  try{ saveGame(); }catch(e){}
}
function avMort(a){
  Array.prototype.slice.call(document.querySelectorAll('.av41-fond')).forEach(function(n){ n.remove(); });
  avParaOuvert = null;
  const f = avFenetre('');
  f.fond.classList.add('av41-mort');
  f.box.style.background = '#1b0d0d'; f.box.style.color = '#f3dede';
  const h = mk('h2', '', trJeu((a && a.titre) || 'Tu es mort')); h.style.color = '#ff8a7a'; f.box.appendChild(h);
  if(a && a.texte) avParagraphes(a.texte, f.box);
  const l = Array.isArray(vars.__parcours) ? vars.__parcours : [];
  if(l.length){ const p = mk('p', '', 'Tes derniers choix : ' + l.slice(-3).join(' \u203A ')); p.style.opacity = '.75'; p.style.fontSize = '.9em'; f.box.appendChild(p); }
  if(vars.__marque){
    const b = avBouton(f, '\u{1F516} Revenir au marque-page', function(){ const t = vars.__marque; f.fermer(); avRestaure(t); });
    b.style.background = '#c0533f';
  }
  const r = avBouton(f, 'Recommencer l\u2019aventure', function(){ f.fermer(); resetProgress(startSceneId()); markSaved(); lancementPartie(); }, false);
  r.style.color = '#f3dede'; r.style.borderColor = '#f3dede';
}
let avMortEnCours = false;
function avVerifieMort(){
  if(avMortEnCours) return;
  const s = avStats().filter(function(x){ return x.mortel && vars['__tire:' + x.id] && vars['car_' + x.id] != null && (parseFloat(vars['car_' + x.id]) || 0) <= 0; })[0];
  if(!s) return;
  avMortEnCours = true;
  setTimeout(function(){ avMortEnCours = false; avMort({ titre: s.mortTitre || 'Tu es mort', texte: s.mortTexte || (s.nom + ' est tomb\xE9e \xE0 z\xE9ro.') }); }, 400);
}

/* --- cartes du destin --- */
function avCarte(id){
  const pq = avTrouve('paquets', id);
  if(!pq) return;
  const tas = [];
  (pq.cartes || []).forEach(function(c){ const n = Math.max(1, Math.min(20, parseInt(c.nb, 10) || 1)); for(let i = 0; i < n; i++) tas.push(c.id + '#' + i); });
  const cle = '__paquet:' + pq.id;
  let tires = Array.isArray(vars[cle]) ? vars[cle].slice() : [];
  let reste = tas.filter(function(x){ return tires.indexOf(x) < 0; });
  if(!reste.length){
    if(pq.remelanger === false){ avToast(trJeu(pq.vide || 'Le paquet est vide.')); return; }
    tires = []; reste = tas.slice();
    if(!reste.length) return;
    avToast('Le paquet est rem\xE9lang\xE9.');
  }
  const pris = reste[Math.floor(Math.random() * reste.length)];
  tires.push(pris); vars[cle] = tires;
  const c = (pq.cartes || []).filter(function(x){ return x.id === pris.split('#')[0]; })[0];
  if(!c) return;
  const f = avFenetre(pq.style, false);
  f.box.remove();
  const carte = mk('div', 'av41-carte'); carte.setAttribute('data-av41-carte', c.id);
  const inn = mk('div', 'av41-carte-in');
  const dos = mk('div', 'av41-face av41-dos');
  const recto = mk('div', 'av41-face av41-recto');
  recto.style.background = f.st.papier; recto.style.color = f.st.encre; recto.style.fontFamily = f.st.police;
  if(c.image){ const im = document.createElement('img'); im.src = c.image; im.alt = ''; recto.appendChild(im); }
  const t = mk('h2', '', trJeu(c.nom || 'Carte')); t.style.color = f.st.accent; t.style.margin = '0 0 8px'; recto.appendChild(t);
  if(c.texte) recto.appendChild(mk('div', '', trJeu(c.texte)));
  const ok = mk('button', 'av41-bouton', 'Continuer'); ok.type = 'button'; ok.style.background = f.st.accent; ok.style.color = '#fff';
  recto.appendChild(ok);
  inn.appendChild(dos); inn.appendChild(recto); carte.appendChild(inn); f.fond.appendChild(carte);
  setTimeout(function(){ carte.classList.add('vue'); try{ hudPlaySound('notify'); }catch(e){} }, 450);
  ok.onclick = function(e){ e.stopPropagation(); f.fermer(); avJouer(c.actions); };
}

/* --- voix int\xE9rieure --- */
function avPensee(a){
  if(a.stat && (parseFloat(vars['car_' + a.stat]) || 0) < (parseFloat(a.min) || 0)) return;
  avCss();
  const d = mk('div', 'av41-pensee');
  d.appendChild(mk('b', '', '\u{1F4AD} ' + trJeu(a.voix || 'Une voix en toi')));
  d.appendChild(document.createTextNode(trJeu(a.texte || '')));
  avCadre().appendChild(d);
  const ms = Math.max(2500, Math.min(12000, String(a.texte || '').length * 70));
  setTimeout(function(){ d.style.opacity = '0'; }, ms);
  setTimeout(function(){ if(d.parentNode) d.remove(); }, ms + 600);
}

/* --- examiner un objet --- */
function avExamen(id){
  const ex = avTrouve('examens', id);
  if(!ex || !ex.image) return;
  const f = avFenetre(ex.style, false);
  f.box.remove();
  const col = mk('div', ''); col.style.cssText = 'width:min(680px,96%);text-align:center;color:#fff;font:15px/1.4 system-ui,sans-serif';
  const titre = mk('div', '', trJeu(ex.nom || 'Examiner')); titre.style.cssText = 'font:600 18px Georgia,serif;margin-bottom:8px';
  const zone = mk('div', 'av41-examen'); zone.setAttribute('data-av41-examen', ex.id);
  zone.style.margin = '0 auto';
  const im = document.createElement('img'); im.src = ex.image; im.alt = ''; im.draggable = false;
  zone.appendChild(im);
  const info = mk('div', '', trJeu(ex.aide || 'Tourne, zoome et touche ce qui attire ton regard.')); info.style.cssText = 'margin-top:8px;min-height:22px;opacity:.85';
  const o = { s: 1, r: 0, x: 0, y: 0 };
  const pose = function(){ im.style.transform = 'translate(-50%,-50%) translate(' + o.x + 'px,' + o.y + 'px) rotate(' + o.r + 'deg) scale(' + o.s + ')'; };
  pose();
  const details = (ex.details || []).filter(function(d){ return d && d.texte; });
  const trouves = function(){ return details.filter(function(d){ return vars['__examen:' + ex.id + ':' + d.id]; }).length; };
  const compte = function(){ return ex.compter !== false && details.length ? ' (' + trouves() + ' / ' + details.length + ')' : ''; };
  titre.textContent = trJeu(ex.nom || 'Examiner') + compte();
  const pts = new Map(); let geste = null, bouge = false;
  zone.addEventListener('pointerdown', function(e){
    try{ zone.setPointerCapture(e.pointerId); }catch(x){}
    pts.set(e.pointerId, { x: e.clientX, y: e.clientY }); bouge = false;
    const l = Array.from(pts.values());
    if(l.length === 2) geste = { d: Math.hypot(l[0].x - l[1].x, l[0].y - l[1].y), a: Math.atan2(l[1].y - l[0].y, l[1].x - l[0].x), s: o.s, r: o.r };
  });
  zone.addEventListener('pointermove', function(e){
    const p = pts.get(e.pointerId); if(!p) return;
    const dx = e.clientX - p.x, dy = e.clientY - p.y;
    if(Math.abs(dx) + Math.abs(dy) > 3) bouge = true;
    pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const l = Array.from(pts.values());
    if(l.length >= 2 && geste){
      const d = Math.hypot(l[0].x - l[1].x, l[0].y - l[1].y), a = Math.atan2(l[1].y - l[0].y, l[1].x - l[0].x);
      o.s = Math.max(1, Math.min(6, geste.s * d / Math.max(10, geste.d)));
      o.r = geste.r + (a - geste.a) * 180 / Math.PI;
    } else if(l.length === 1){ o.x += dx; o.y += dy; }
    pose();
  });
  const lacher = function(e){
    const p = pts.get(e.pointerId);
    pts.delete(e.pointerId); if(pts.size < 2) geste = null;
    if(!p || bouge || pts.size) return;
    // un toucher : retrouver l'endroit de l'image, malgr\xE9 le zoom et la rotation
    const r = zone.getBoundingClientRect();
    const cx = r.left + r.width / 2 + o.x, cy = r.top + r.height / 2 + o.y;
    let vx = e.clientX - cx, vy = e.clientY - cy;
    const ang = -o.r * Math.PI / 180;
    const rx = vx * Math.cos(ang) - vy * Math.sin(ang), ry = vx * Math.sin(ang) + vy * Math.cos(ang);
    const u = 0.5 + rx / o.s / im.offsetWidth, v = 0.5 + ry / o.s / im.offsetHeight;
    let meilleur = null, dm = 0.09 / Math.sqrt(o.s);
    details.forEach(function(d){ const dd = Math.hypot((d.x || 0) - u, (d.y || 0) - v); if(dd < dm){ dm = dd; meilleur = d; } });
    if(!meilleur){ info.textContent = trJeu(ex.rien || 'Rien de particulier ici.'); return; }
    if((parseFloat(meilleur.zoom) || 1) > o.s + 0.01){ info.textContent = trJeu('Il y a quelque chose\u2026 approche-toi davantage.'); return; }
    info.textContent = trJeu(meilleur.texte);
    const cle = '__examen:' + ex.id + ':' + meilleur.id;
    if(!vars[cle]){
      vars[cle] = 1;
      try{ hudPlaySound('notify'); }catch(x){}
      if(meilleur.actions && meilleur.actions.length){ try{ runActionsNow(normalizeActions(meilleur.actions)); }catch(x){} }
      titre.textContent = trJeu(ex.nom || 'Examiner') + compte();
      if(details.length && trouves() === details.length && ex.fini) info.textContent = trJeu(meilleur.texte) + ' \u2014 ' + trJeu(ex.fini);
    }
  };
  zone.addEventListener('pointerup', lacher);
  zone.addEventListener('pointercancel', function(e){ pts.delete(e.pointerId); geste = null; });
  zone.addEventListener('wheel', function(e){ e.preventDefault(); o.s = Math.max(1, Math.min(6, o.s * (e.deltaY < 0 ? 1.12 : 0.89))); pose(); }, { passive: false });
  const outils = mk('div', 'av41-outils');
  const outil = function(t, fn, lab){ const b = mk('button', '', t); b.type = 'button'; b.setAttribute('aria-label', lab); b.onclick = function(e){ e.stopPropagation(); fn(); pose(); }; outils.appendChild(b); };
  outil('\u21BA', function(){ o.r -= 45; }, 'Tourner \xE0 gauche');
  outil('\u21BB', function(){ o.r += 45; }, 'Tourner \xE0 droite');
  outil('\u2212', function(){ o.s = Math.max(1, o.s / 1.3); }, 'D\xE9zoomer');
  outil('+', function(){ o.s = Math.min(6, o.s * 1.3); }, 'Zoomer');
  outil('\u27F2', function(){ o.s = 1; o.r = 0; o.x = 0; o.y = 0; }, 'Recentrer');
  outil('Fermer', function(){ f.fermer(); avJouer(trouves() === details.length ? ex.actions : []); }, 'Fermer');
  col.appendChild(titre); col.appendChild(zone); col.appendChild(info); col.appendChild(outils);
  f.fond.appendChild(col);
}

/* --- photo-preuve : viser le bon endroit de la sc\xE8ne --- */
function avPhoto(id){
  const ph = avTrouve('photos', id);
  if(!ph) return;
  const f = avFenetre('', true);
  f.fond.setAttribute('data-av41-photo', ph.id);
  const viseur = mk('div', 'av41-viseur');
  f.fond.appendChild(viseur);
  const aide = mk('div', 'av41-toast', trJeu(ph.consigne || ('Photographie : ' + (ph.nom || 'la preuve'))));
  aide.style.pointerEvents = 'none'; f.fond.appendChild(aide);
  const declic = mk('button', 'av41-declic'); declic.type = 'button'; declic.setAttribute('aria-label', 'Prendre la photo'); declic.setAttribute('data-av41-declic', '1');
  const annuler = mk('button', 'av41-annuler', 'Ranger l\u2019appareil'); annuler.type = 'button';
  f.fond.appendChild(declic); f.fond.appendChild(annuler);
  annuler.onclick = function(e){ e.stopPropagation(); f.fermer(); };
  declic.onclick = function(e){
    e.stopPropagation();
    const fl = mk('div', 'av41-flash'); avCadre().appendChild(fl); setTimeout(function(){ fl.remove(); }, 500);
    try{ hudPlaySound('notify'); }catch(x){}
    let bon = false;
    if(!ph.sceneId || (current && current.id === ph.sceneId)){
      camera.updateMatrixWorld();
      const n = yawPitchToDir(ph.yaw || 0, ph.pitch || 0).multiplyScalar(100).project(camera);
      const tol = Math.max(0.08, Math.min(0.9, parseFloat(ph.tolerance) || 0.3));
      bon = n.z < 1 && Math.abs(n.x) < tol && Math.abs(n.y) < tol;
    }
    if(!bon){ aide.textContent = trJeu(ph.rate || 'La photo ne montre rien d\u2019utile.'); return; }
    f.fermer();
    const album = Array.isArray(vars.__album) ? vars.__album.slice() : [];
    if(album.indexOf(ph.nom || ph.id) < 0) album.push(ph.nom || ph.id);
    vars.__album = album; vars['__photo:' + ph.id] = 1;
    avToast('\u{1F4F7} ' + trJeu(ph.reussi || ('Preuve : ' + (ph.nom || 'photo'))));
    avJouer(ph.actions);
  };
}

/* --- d\xE9duction \xE0 trous --- */
function avDeduction(id){
  const d = avTrouve('deductions', id);
  if(!d) return;
  const morceaux = String(d.phrase || '').split('___');
  const nb = morceaux.length - 1;
  if(nb < 1) return;
  const motsCodes = (GAME.variables || []).filter(function(v){ return v && String(v.key).indexOf('mot_') === 0; });
  let mots = String(d.mots || '').split(',').map(function(x){ return x.trim(); }).filter(Boolean);
  if(d.trouves){
    mots = mots.filter(function(m){
      const mc = motsCodes.filter(function(v){ return foldJeu(v.label || v.key.slice(4)) === foldJeu(m); })[0];
      return !mc || !!vars[mc.key];
    });
  }
  const f = avFenetre(d.style);
  f.fond.setAttribute('data-av41-deduction', d.id);
  const h = mk('h2', '', trJeu(d.titre || 'D\xE9duction')); h.style.color = f.st.accent; f.box.appendChild(h);
  const phrase = mk('p', ''); phrase.style.lineHeight = '2.4';
  const champs = [];
  morceaux.forEach(function(m, i){
    phrase.appendChild(document.createTextNode(trJeu(m)));
    if(i < nb){
      const s = document.createElement('select'); s.className = 'av41-trou';
      const vide = document.createElement('option'); vide.value = ''; vide.textContent = '\u2026'; s.appendChild(vide);
      mots.forEach(function(w){ const o = document.createElement('option'); o.value = w; o.textContent = trJeu(w); s.appendChild(o); });
      phrase.appendChild(s); champs.push(s);
    }
  });
  f.box.appendChild(phrase);
  const rep = mk('p', ''); rep.style.minHeight = '1.4em'; rep.style.fontWeight = '600';
  f.box.appendChild(rep);
  const sol = (Array.isArray(d.solution) ? d.solution : []).map(foldJeu);
  avBouton(f, 'V\xE9rifier', function(){
    let justes = 0;
    champs.forEach(function(s, i){ if(s.value && foldJeu(s.value) === sol[i]) justes++; });
    if(justes === nb){
      vars['__deduction:' + d.id] = 1;
      f.fermer();
      avToast('\u2714 ' + trJeu(d.reussi || 'C\u2019est \xE7a !'), 2600);
      avJouer(d.actions);
      return;
    }
    vars['__deduction_essais:' + d.id] = (parseFloat(vars['__deduction_essais:' + d.id]) || 0) + 1;
    rep.textContent = d.aide === false ? trJeu('Ce n\u2019est pas encore \xE7a.') : justes + ' sur ' + nb + ' ' + (justes > 1 ? 'sont justes.' : 'est juste.');
    rep.style.color = f.st.accent;
  });
  avBouton(f, 'Plus tard', f.fermer, false);
}
function foldJeu(t){ return String(t || '').toLowerCase().normalize('NFD').split('').filter(function(c){ const k = c.charCodeAt(0); return k < 768 || k > 879; }).join('').trim(); }

/* --- pile de la lampe --- */
function avPileOk(){
  const p = av41().pile || {};
  if(!p.active) return true;
  if(vars.__pile == null) avInit();
  return (parseFloat(vars.__pile) || 0) > 0;
}
setInterval(function(){
  try{
    avFeuilleBouton();
    const p = av41().pile || {};
    if(!p.active || playerScreen !== 'playing' || !current || !current.lampe) return;
    const l = current.lampe;
    if(l.objet && !(inventory[l.objet] > 0)) return;
    if(vars.__pile == null) avInit();
    const avant = parseFloat(vars.__pile) || 0;
    if(avant <= 0) return;
    const apres = Math.max(0, avant - 1);
    vars.__pile = apres;
    const seuil = parseFloat(p.avertir) || 0;
    if(seuil > 0 && avant > seuil && apres <= seuil) avToast('\u{1F526} ' + trJeu(p.texteFaible || 'La pile faiblit\u2026'));
    if(apres <= 0){ avToast('\u{1F526} ' + trJeu(p.texteVide || 'La pile est vide.')); try{ lampeDessine(true); }catch(e){} }
  }catch(e){}
}, 1000);

/* --- ce que fait chaque action du lot 41 dans le jeu --- */
function avEffet(e){
  const a = e.action || {};
  if(a.type === 'av_paragraphe') avQuandLibre(function(){ avPage(a.num); });
  else if(a.type === 'av_feuille') avQuandLibre(avFeuille);
  else if(a.type === 'av_test') avDesMontre(e.r, a);
  else if(a.type === 'av_marque') avMarque(a);
  else if(a.type === 'av_mort') avMort(a);
  else if(a.type === 'av_mot'){ if(a.mode !== 'retirer' && a.annoncer !== false){ const v = (GAME.variables || []).filter(function(x){ return x.key === 'mot_' + a.mot; })[0]; avToast('\u2712 Mot-code : ' + String(v ? v.label : a.mot).toUpperCase()); } }
  else if(a.type === 'av_journal'){ if(a.annoncer) avToast('\u{1F4D6} Journal : ' + trJeu(a.texte || '')); }
  else if(a.type === 'av_carte') avQuandLibre(function(){ avCarte(a.paquetId); });
  else if(a.type === 'av_pensee') avPensee(a);
  else if(a.type === 'av_examiner') avQuandLibre(function(){ avExamen(a.examenId); });
  else if(a.type === 'av_photo') avQuandLibre(function(){ avPhoto(a.photoId); });
  else if(a.type === 'av_deduction') avQuandLibre(function(){ avDeduction(a.deductionId); });
  else if(a.type === 'av_pile'){ avToast('\u{1F526} Pile recharg\xE9e'); try{ lampeDessine(true); }catch(x){} }
}

/* --- le fil de l'histoire : seulement quand on teste depuis l'\xE9diteur --- */
const avFil = { liste: [], avant: null, el: null, replie: false };
function avPhoto41Etat(){
  const v = {}; Object.keys(vars).forEach(function(k){ if(k.indexOf('__') !== 0 || k === '__para') v[k] = vars[k]; });
  return { inv: JSON.stringify(inventory), vars: v, scene: current ? current.id : '' };
}
function avFilDiff(a, b){
  const l = [];
  if(a.scene !== b.scene){ const s = GAME.scenes.filter(function(x){ return x.id === b.scene; })[0]; l.push('Sc\xE8ne : ' + (s ? s.name || s.id : b.scene)); }
  const ia = JSON.parse(a.inv || '{}'), ib = JSON.parse(b.inv || '{}');
  Object.keys(Object.assign({}, ia, ib)).forEach(function(k){
    if((ia[k] || 0) !== (ib[k] || 0)){ const it = (GAME.items || []).filter(function(x){ return x.id === k; })[0]; l.push((it ? it.name : k) + ' : ' + (ia[k] || 0) + ' \u2192 ' + (ib[k] || 0)); }
  });
  Object.keys(Object.assign({}, a.vars, b.vars)).forEach(function(k){
    const x = JSON.stringify(a.vars[k]), y = JSON.stringify(b.vars[k]);
    if(x !== y) l.push(k + ' : ' + (x === undefined ? '\u2013' : x) + ' \u2192 ' + (y === undefined ? '\u2013' : y));
  });
  return l;
}
function avFilDessine(){
  if(!avFil.el){
    avCss();
    avFil.el = mk('div', 'av41-fil'); avFil.el.setAttribute('data-av41-fil', '1');
    avFil.el.addEventListener('pointerdown', function(e){ e.stopPropagation(); });
    avFil.el.addEventListener('click', function(e){ e.stopPropagation(); });
    avCadre().appendChild(avFil.el);
  }
  const el = avFil.el; el.textContent = '';
  const tete = mk('div', ''); tete.style.cssText = 'display:flex;justify-content:space-between;align-items:center;gap:6px;font-weight:600';
  tete.appendChild(mk('span', '', '\u{1F9F5} Fil de l\u2019histoire (' + avFil.liste.length + ')'));
  const rep = mk('button', '', avFil.replie ? 'Ouvrir' : 'Replier'); rep.type = 'button';
  rep.onclick = function(){ avFil.replie = !avFil.replie; avFilDessine(); };
  tete.appendChild(rep); el.appendChild(tete);
  if(avFil.replie) return;
  avFil.liste.slice().reverse().slice(0, 40).forEach(function(en){
    const r = mk('div', 'av41-f-entree');
    const t = mk('div', ''); t.style.flex = '1';
    t.appendChild(mk('div', '', en.h + ' \xB7 ' + en.l.slice(0, 4).join(' ; ') + (en.l.length > 4 ? ' \u2026' : '')));
    r.appendChild(t);
    const b = mk('button', '', '\u21B6'); b.type = 'button'; b.title = 'Revenir juste avant ce changement';
    b.onclick = function(){
      const s = en.avant;
      inventory = JSON.parse(s.inv || '{}');
      const garde = {}; Object.keys(vars).forEach(function(k){ if(k.indexOf('__') === 0 && k !== '__para') garde[k] = vars[k]; });
      vars = Object.assign(garde, s.vars);
      if(s.scene && current && current.id !== s.scene) loadScene(s.scene);
      try{ renderHotspots(); hudSync(); }catch(x){}
      avFil.avant = avPhoto41Etat();
      avFil.liste = avFil.liste.slice(0, avFil.liste.indexOf(en));
      avToast('\u21B6 Retour en arri\xE8re');
      avFilDessine();
    };
    r.appendChild(b);
    el.appendChild(r);
  });
}
if(EN_TEST && av41().fil !== false){
  setInterval(function(){
    try{
      if(playerScreen === 'home') return;
      const n = avPhoto41Etat();
      if(!avFil.avant){ avFil.avant = n; avFilDessine(); return; }
      const l = avFilDiff(avFil.avant, n);
      if(!l.length) return;
      const d = new Date();
      avFil.liste.push({ h: String(d.getMinutes()).padStart(2, '0') + ':' + String(d.getSeconds()).padStart(2, '0'), l: l, avant: avFil.avant });
      if(avFil.liste.length > 60) avFil.liste.shift();
      avFil.avant = n;
      avFilDessine();
    }catch(e){}
  }, 700);
}
