function mRgba(hex, a){
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(String(hex || ''));
  return m ? 'rgba(' + parseInt(m[1], 16) + ',' + parseInt(m[2], 16) + ',' + parseInt(m[3], 16) + ',' + a + ')' : (hex || 'transparent');
}
function mLookDe(b){ return b.look || {}; }
function mVitrineDe(b){ return b.vitrine || { mode: 'liste' }; }
function mAnimClasse(b){ const a = mLookDe(b).anim; return a && a !== 'none' && !HomeSettings.get().reduceMotion ? ' mq-a-' + a : ''; }
function mEtiquette(b, pos, texte){
  const e = mVitrineDe(b).etiquette || {}, p = pos || {}, L = mLookDe(b);
  const t = mk('div', 'mq-tag', texte);
  const x = p.x != null ? p.x : e.x, y = p.y != null ? p.y : e.y, k = p.taille != null ? p.taille : e.taille;
  t.style.left = (x * 100) + '%';
  t.style.top = (y * 100) + '%';
  t.style.transform = 'translate(-50%,-50%) rotate(' + (e.rotation || 0) + 'deg) scale(' + (k || 1) + ')';
  t.style.color = e.couleur || '#14161C';
  t.style.fontWeight = e.gras === false ? '400' : '700';
  if(e.police || L.police) t.style.fontFamily = '"' + (e.police || L.police) + '", system-ui, sans-serif';
  t.style.borderRadius = (e.rayon || 0) + 'px';
  if(e.image){ t.style.background = 'url("' + e.image + '") center/100% 100% no-repeat'; }
  else t.style.background = mRgba(e.fond || b.couleur || '#E8A33D', e.opacite == null ? 1 : e.opacite);
  return t;
}
function mTexteEtiquette(b, m, p){
  if(!p) return 'Gratuit';
  const e = mVitrineDe(b).etiquette || {};
  return e.icone === false ? String(p) : mMontant(m, p);
}
function mFiche(b, o){
  const v = boutiqueV;
  if(!v) return;
  if(mFicheLibre35(b, o)) return;
  const f = mk('div', 'mq-fiche');
  const boite = mk('div', 'mq-fiche-boite');
  boite.style.color = mLookDe(b).texte || '#E9E6DD';
  boite.style.background = mRgba(mLookDe(b).panneauCouleur || '#14171F', 1);
  if(o.image){ const im = document.createElement('img'); im.src = o.image; im.alt = ''; boite.appendChild(im); }
  boite.appendChild(mk('div', 'mq-nom', o.titre));
  if(o.texte) boite.appendChild(mk('div', 'mq-petit', o.texte));
  o.boutons.forEach(function(x){ mBouton(boite, x.texte, x.fn, x.second, x.off); });
  mBouton(boite, 'Retour', function(){ f.remove(); }, true);
  f.appendChild(boite);
  f.addEventListener('click', function(e){ if(e.target === f) f.remove(); });
  v.el.querySelector('.mq-boite').appendChild(f);
}
function mCarte(b, o){
  const vi = mVitrineDe(b), L = mLookDe(b);
  const c = mk('button', 'mq-carte' + (o.off ? ' mq-epuise' : ''));
  c.type = 'button';
  c.style.aspectRatio = '1 / ' + (vi.ratio || 1.25);
  c.style.borderRadius = (L.carteRayon == null ? 10 : L.carteRayon) + 'px';
  if(L.carteImage) c.style.background = 'url("' + L.carteImage + '") center/100% 100% no-repeat';
  else c.style.background = mRgba(L.carteCouleur || '#FFFFFF', L.carteOpacite == null ? 0.06 : L.carteOpacite);
  if(o.image){
    const im = document.createElement('img');
    im.className = 'mq-png' + mAnimClasse(b); im.alt = ''; im.src = o.image;
    im.style.width = im.style.height = ((vi.tailleImage || 0.8) * 100) + '%';
    c.appendChild(im);
  }
  if(vi.noms !== false || !o.image) c.appendChild(mk('div', 'mq-carte-nom', o.nom));
  c.appendChild(mEtiquette(b, o.pos, o.prix));
  c.setAttribute('aria-label', o.nom + ', ' + o.prix);
  c.addEventListener('click', o.fn);
  return c;
}
function mDonneesAchat(b, l){
  const it = mObjet(l.itemId), m = mMonnaie(l.monnaieId || b.monnaieId), p = mPrix(b, l), reste = mReste(b, l), remise = mRemise(b);
  const info = [];
  if(it.description) info.push(trJeu(it.description));
  if(reste !== Infinity) info.push(reste ? 'Reste ' + reste : '\xC9puis\xE9');
  if(remise > 0) info.push('Remise ' + remise + ' %');
  return { it: it, m: m, p: p, reste: reste, info: info.join(' \xB7 '), image: l.image || it.image, nom: trJeu(it.name) };
}
function mClicAchat(b, l, cible){
  const d = mDonneesAchat(b, l);
  if(mVitrineDe(b).clic === 'achat'){ mAcheter(b, l, cible); return; }
  const boutons = [{ texte: (d.p ? 'Acheter \xB7 ' + mMontant(d.m, d.p) : 'Prendre'), fn: function(){ mAcheter(b, l, null); }, off: !d.reste }];
  if(b.marchandage && b.marchandage.actif && d.p > 0 && d.reste && vars[mCle('neg', b, l.itemId)] == null){
    boutons.push({ texte: 'Marchander', second: true, fn: function(){ mMarchander(b, l, d.it); } });
  }
  mFiche(b, { image: d.image, titre: d.nom, texte: d.info, prixTexte: d.p ? mMontant(d.m, d.p) : 'Gratuit', boutons: boutons });
}
function mVitrineAcheter(b, liste){
  const vi = mVitrineDe(b);
  const lignes = (b.stock || []).filter(function(l){ return l.itemId && mObjet(l.itemId) && mCondsOk(l.conditions); });
  if(!lignes.length){ liste.appendChild(mk('div', 'mq-vide', 'Rien \xE0 vendre pour le moment.')); return; }
  if(vi.mode === 'libre'){
    const d = mk('div', 'mq-decor');
    d.style.aspectRatio = '1 / ' + (vi.sceneRatio || 1.2);
    if(vi.decor) d.style.backgroundImage = 'url("' + vi.decor + '")';
    const tous = (b.stock || []).filter(function(l){ return l.itemId; });
    lignes.forEach(function(l){
      const k = tous.indexOf(l), n = tous.length, cols = Math.min(3, Math.max(1, n));
      const x = l.x != null ? l.x : (k % cols + 0.5) / cols, y = l.x != null ? l.y : (Math.floor(k / cols) + 0.5) / Math.ceil(n / cols);
      const o = mDonneesAchat(b, l);
      const c = mk('button', 'mq-pose' + (o.reste ? '' : ' mq-epuise'));
      c.type = 'button';
      c.style.left = (x * 100) + '%'; c.style.top = (y * 100) + '%';
      c.style.width = ((l.taille != null ? l.taille : 0.3) * 100) + '%';
      if(o.image){ const im = document.createElement('img'); im.alt = ''; im.src = o.image; if(mAnimClasse(b)) im.className = mAnimClasse(b).trim(); c.appendChild(im); }
      if(vi.noms !== false || !o.image) c.appendChild(mk('div', 'mq-carte-nom', o.nom));
      c.appendChild(mEtiquette(b, l.prixPos, mTexteEtiquette(b, o.m, o.p)));
      c.setAttribute('aria-label', o.nom);
      c.addEventListener('click', function(){ mClicAchat(b, l, c); });
      d.appendChild(c);
    });
    liste.appendChild(d);
    return;
  }
  const g = mGrille(b);
  lignes.forEach(function(l){
    const o = mDonneesAchat(b, l);
    const c = mCarte(b, { image: o.image, nom: o.nom, prix: mTexteEtiquette(b, o.m, o.p), pos: l.prixPos, off: !o.reste, fn: function(){ mClicAchat(b, l, c); } });
    g.appendChild(c);
  });
  liste.appendChild(g);
}
function mGrille(b){
  const vi = mVitrineDe(b), g = mk('div', 'mq-grille');
  g.style.gridTemplateColumns = 'repeat(' + (vi.colonnes || 2) + ', minmax(0, 1fr))';
  g.style.gap = (vi.ecart == null ? 8 : vi.ecart) + 'px';
  return g;
}
function mVitrineVendre(b, liste){
  const stock = (b.stock || []).map(function(l){ return l.itemId; });
  const ids = Object.keys(inventory).filter(function(id){
    if(uiNumberOf(inventory[id]) <= 0 || !mObjet(id) || mRevente(b, id) == null) return false;
    return b.rachat.seulement !== 'stock' || stock.indexOf(id) >= 0;
  });
  if(!ids.length){ liste.appendChild(mk('div', 'mq-vide', 'Rien \xE0 vendre dans ton sac.')); return; }
  const m = mMonnaie(b.monnaieId), g = mGrille(b);
  ids.forEach(function(id){
    const it = mObjet(id), p = mRevente(b, id), n = uiNumberOf(inventory[id]), nom = trJeu(it.name) + (n > 1 ? ' \xD7 ' + n : '');
    const l = (b.stock || []).filter(function(x){ return x.itemId === id; })[0] || {};
    const image = l.image || it.image;
    g.appendChild(mCarte(b, { image: image, nom: nom, prix: mTexteEtiquette(b, m, p), pos: l.prixPos, fn: function(){
      if(mVitrineDe(b).clic === 'achat'){ mVendre(b, id, it, p, m); return; }
      mFiche(b, { vente: true, prixTexte: mMontant(m, p), image: image, titre: nom, texte: it.description ? trJeu(it.description) : '', boutons: [{ texte: 'Vendre \xB7 ' + mMontant(m, p), fn: function(){ mVendre(b, id, it, p, m); } }] });
    } }));
  });
  liste.appendChild(g);
}
/*  L'allure choisie pour cette boutique, pos\xE9e sur ce qui vient d'\xEAtre dessin\xE9. */
function mAllure(b, el, boite){
  const L = mLookDe(b);
  if(!b.look) return;
  boite.style.color = L.texte;
  boite.style.borderRadius = L.rayon + 'px';
  boite.style.background = mRgba(L.panneauCouleur, L.panneauOpacite);
  if(L.panneauImage){ boite.style.backgroundImage = 'url("' + L.panneauImage + '")'; boite.style.backgroundSize = '100% 100%'; }
  if(L.police) boite.style.fontFamily = '"' + L.police + '", system-ui, sans-serif';
  el.style.padding = L.plein ? '0' : '';
  if(L.plein){
    boite.style.maxWidth = 'none'; boite.style.width = '100%'; boite.style.height = '100%'; boite.style.borderRadius = '0'; boite.style.border = 'none';
    const tete = boite.querySelector('.mq-tete'), x = boite.querySelector('.mq-x');
    if(tete) tete.style.paddingTop = 'calc(12px + env(safe-area-inset-top,0px))';
    if(x) x.style.top = 'calc(8px + env(safe-area-inset-top,0px))';
  }
  const nom = boite.querySelector('.mq-nom');
  if(nom){
    if(L.police) nom.style.fontFamily = '"' + L.police + '", Georgia, serif';
    if(L.enseigne){
      nom.textContent = '';
      const im = document.createElement('img'); im.src = L.enseigne; im.alt = trJeu(b.nom);
      im.style.maxHeight = '64px'; im.style.maxWidth = '100%'; im.style.display = 'block';
      nom.appendChild(im);
    }
  }
}


