/*  Ce que l'auteur a choisi de retirer : il ne reste que ses images.
    Le bouton Fermer reste toujours, sinon on ne sortirait plus.      */
function mEpure35(b, el, boite){
  const L = mLookDe(b), c = L.cacher || {}, vi = mVitrineDe(b);
  const cache = function(s){ boite.querySelectorAll(s).forEach(function(n){ n.style.display = 'none'; }); };
  if(c.titre && !L.enseigne) cache('.mq-nom');
  if(c.solde) cache('.mq-solde');
  const tete = boite.querySelector('.mq-tete');
  if(tete && ![].some.call(tete.children, function(n){ return n.style.display !== 'none'; })) tete.style.display = 'none';
  if(c.onglets) cache('.mq-onglets');
  if(c.marchand) cache('.mq-parole');
  if(c.prix) cache('.mq-tag');
  if(c.panneau){
    boite.style.backgroundColor = 'transparent';
    boite.querySelectorAll('.mq-carte').forEach(function(n){ if(!L.carteImage) n.style.background = 'transparent'; });
  }
  if(c.ombre){ boite.style.boxShadow = 'none'; boite.style.border = 'none'; }
  if(c.voile){
    el.style.backgroundColor = 'transparent';
    el.style.backgroundImage = b.image ? 'url("' + b.image + '")' : 'none';
  }
  const x = boite.querySelector('.mq-x');
  if(x && vi.fermerImage){ x.textContent = ''; x.style.background = 'transparent url("' + vi.fermerImage + '") center/contain no-repeat'; }
}
/*  Le d\xE9cor \xAB plac\xE9 \xE0 la main \xBB pos\xE9 o\xF9 l'auteur l'a voulu sur l'\xE9cran.
    Panneau plein \xE9cran : seul le d\xE9cor bouge. Sinon, tout le panneau suit. */
function mPlaceDecor35(b, v, el, boite){
  if(v.placeRO){ try{ v.placeRO.disconnect(); }catch(e){} v.placeRO = null; }
  const vi = mVitrineDe(b), p = vi.place;
  if(vi.mode !== 'libre' || !p || p.x == null || v.onglet !== 'acheter') return;
  const d = boite.querySelector('.mq-decor');
  if(!d) return;
  const L = mLookDe(b), ratio = vi.sceneRatio || 1.2;
  const x = boite.querySelector('.mq-x');
  if(x) x.style.zIndex = '8';
  boite.querySelectorAll('.mq-tete,.mq-parole,.mq-onglets').forEach(function(n){ n.style.position = 'relative'; n.style.zIndex = '2'; });
  const pose = function(){
    const W = el.clientWidth, H = el.clientHeight;
    if(!W || !H) return;
    if(L.plein){
      const r = mqFondDecor(W, H, ratio, p.largeur, p.x, p.y);
      d.style.position = 'absolute';
      d.style.left = r.x + 'px'; d.style.top = r.y + 'px';
      d.style.width = r.w + 'px'; d.style.height = r.h + 'px';
      return;
    }
    boite.style.position = 'absolute'; boite.style.boxSizing = 'border-box';
    boite.style.maxWidth = 'none'; boite.style.maxHeight = 'none';
    boite.style.width = Math.min(p.largeur * W, W) + 'px';
    const pad = boite.offsetWidth - d.offsetWidth, tete = boite.offsetHeight - d.offsetHeight;
    const r = mqFondDecor(W, Math.max(H - tete, 60), ratio, p.largeur, p.x, p.y);
    boite.style.width = (Math.min(r.w, W - pad) + pad) + 'px';
    const borne = function(a, m){ return Math.max(0, Math.min(Math.max(0, m), a)); };
    boite.style.left = borne(p.x * W - d.offsetWidth / 2 - d.offsetLeft, W - boite.offsetWidth) + 'px';
    boite.style.top = borne(p.y * H - d.offsetHeight / 2 - d.offsetTop, H - boite.offsetHeight) + 'px';
  };
  pose();
  if(window.ResizeObserver){ v.placeRO = new ResizeObserver(pose); v.placeRO.observe(el); }
}
/*  La fiche d'un objet, compos\xE9e dans l'\xE9diteur : chaque partie a sa place,
    son allure, et peut dispara\xEEtre.                                       */
function mFicheLibre35(b, o){
  const v = boutiqueV, F = mVitrineDe(b).fiche, L = mLookDe(b);
  if(!v || !F || !F.parties) return false;
  const P = F.parties, f = mk('div', 'mq-fl'), p = mk('div', 'mq-fl-p'), polices = [];
  const ferme = function(){ f.remove(); };
  f.style.background = mRgba(F.voile, F.voileOpacite);
  p.style.color = L.texte || '#E9E6DD';
  if(F.fondVoir){
    p.style.borderRadius = F.rayon + 'px';
    if(F.fondImage) p.style.background = 'url("' + F.fondImage + '") center/100% 100% no-repeat';
    else p.style.background = mRgba(F.fondCouleur || L.panneauCouleur || '#14171F', F.fondOpacite);
  }
  const pose = function(n, e){
    const q = P[n];
    e.classList.add('mq-fl-e');
    e.style.left = ((q.x - q.l / 2) * 100) + '%'; e.style.top = ((q.y - q.h / 2) * 100) + '%';
    e.style.width = (q.l * 100) + '%'; e.style.height = (q.h * 100) + '%';
    if(q.couleur) e.style.color = q.couleur;
    e.style.fontWeight = q.gras ? '700' : '400';
    const police = q.police || L.police;
    if(police) e.style.fontFamily = '"' + police + '", system-ui, sans-serif';
    polices.push([e, q.taille]);
  };
  const texte = function(n, t, serif){
    if(!P[n].voir || !t) return;
    const e = mk('div', 'mq-fl-t', t);
    e.style.textAlign = P[n].align;
    pose(n, e);
    if(serif && !P[n].police && !L.police) e.style.fontFamily = 'Georgia, serif';
    p.appendChild(e);
  };
  const bouton = function(n, libelle, fn, second, off){
    if(!P[n].voir) return;
    const e = mBouton(p, libelle, fn, second, off), q = P[n];
    pose(n, e);
    if(q.image){ e.style.background = 'transparent url("' + q.image + '") center/100% 100% no-repeat'; e.style.borderRadius = '0'; }
    else if(q.fond) e.style.background = q.fond;
  };
  const a = o.boutons[0], neg = o.boutons[1];
  if(o.image && P.image.voir){
    const im = document.createElement('img');
    im.src = o.image; im.alt = '';
    pose('image', im);
    if(a && !P.achat.voir && !a.off) im.addEventListener('click', a.fn);
    p.appendChild(im);
  }
  texte('nom', o.titre, true);
  texte('texte', o.texte);
  texte('prix', o.prixTexte);
  if(neg) bouton('marchander', trJeu(P.marchander.texte), neg.fn, true, neg.off);
  if(a){
    const mod = P.achat.texte;
    bouton('achat', o.vente || mod === 'Acheter \xB7 {prix}' ? a.texte : trJeu(mod).split('{prix}').join(o.prixTexte || ''), a.fn, false, a.off);
  }
  bouton('retour', trJeu(P.retour.texte), ferme, true);
  f.appendChild(p);
  f.addEventListener('click', function(e){
    if(e.target === f || (!P.retour.voir && !(e.target.closest && e.target.closest('button')))) ferme();
  });
  const cale = function(){
    const W = v.el.clientWidth, H = v.el.clientHeight;
    if(!W || !H) return;
    const r = mqFondDecor(W, H, F.ratio, F.largeur / W, F.x, F.y), k = r.w / F.largeur;
    p.style.left = r.x + 'px'; p.style.top = r.y + 'px';
    p.style.width = r.w + 'px'; p.style.height = r.h + 'px';
    polices.forEach(function(x){ x[0].style.fontSize = (x[1] * k) + 'px'; });
  };
  v.el.appendChild(f);
  cale();
  if(window.ResizeObserver) new ResizeObserver(cale).observe(f);
  return true;
}
function mFondActif(b, v){ return !!b.vitrine && b.vitrine.mode === 'fond' && v.onglet === 'acheter'; }
function mFondDessine(b, v, el){
  const vi = mVitrineDe(b), I = vi.info || {}, L = mLookDe(b), fond = vi.decor || b.image || '';
  if(v.fondRO){ try{ v.fondRO.disconnect(); }catch(e){} v.fondRO = null; }
  if(v.fmin){ clearTimeout(v.fmin); v.fmin = 0; }
  el.textContent = '';
  el.style.padding = '0';
  if(fond) el.style.backgroundImage = 'url("' + fond + '")';
  const scene = mk('div', 'mq-fs');
  if(fond) scene.style.backgroundImage = 'url("' + fond + '")';
  scene.style.setProperty('--mq-z', String(vi.zoom || 1.15));
  scene.style.setProperty('--mq-os', (vi.ombreTaille == null ? 18 : vi.ombreTaille) + 'px');
  scene.style.setProperty('--mq-oc', vi.ombre || '#FFD27A');
  el.appendChild(scene);
  const tous = (b.stock || []).filter(function(l){ return l.itemId; });
  const lignes = tous.filter(function(l){ return mObjet(l.itemId) && mCondsOk(l.conditions); });
  if(!lignes.length && !v.dit) v.dit = 'Rien \xE0 vendre pour le moment.';
  const objets = lignes.map(function(l){
    const k = tous.indexOf(l), a = l.x != null ? { x: l.x, y: l.y } : mqFondAuto(k, tous.length), o = mDonneesAchat(b, l);
    const c = mk('button', 'mq-fo' + (o.reste ? '' : ' mq-epuise'));
    c.type = 'button';
    c.setAttribute('aria-label', o.nom);
    if(l.ombre) c.style.setProperty('--mq-oc', l.ombre);
    if(o.image){ const im = document.createElement('img'); im.alt = ''; im.src = o.image; im.draggable = false; if(mAnimClasse(b)) im.className = mAnimClasse(b).trim(); c.appendChild(im); }
    else c.appendChild(mk('div', 'mq-fo-vide', o.nom));
    scene.appendChild(c);
    return { i: (b.stock || []).indexOf(l), l: l, o: o, c: c, x: a.x, y: a.y, t: l.taille != null ? l.taille : 0.2, px: 0, py: 0, pt: 0 };
  });
  const haut = mk('div', 'mq-fh');
  const ca = L.cacher || {};
  if(!ca.solde) (marche().monnaies || []).forEach(function(m){ haut.appendChild(mk('div', 'mq-solde', mMontant(m, mSolde(m)))); });
  const onglets = [['acheter', 'Acheter']];
  if(b.rachat && b.rachat.actif) onglets.push(['vendre', 'Vendre']);
  if((b.trocs || []).length) onglets.push(['troc', 'Troc']);
  if(onglets.length > 1 && !ca.onglets){
    const bo = mk('div', 'mq-onglets');
    onglets.forEach(function(t){
      const bt = mk('button', t[0] === v.onglet ? 'on' : '', t[1]);
      bt.type = 'button';
      bt.addEventListener('click', function(){ v.onglet = t[0]; mDessine(); });
      bo.appendChild(bt);
    });
    haut.appendChild(bo);
  }
  el.appendChild(haut);
  const x = mk('button', 'mq-x mq-fs-x', vi.fermerImage ? '' : '\u2715');
  x.type = 'button'; x.setAttribute('aria-label', 'Fermer');
  if(vi.fermerImage){ x.style.backgroundColor = 'transparent'; x.style.backgroundImage = 'url("' + vi.fermerImage + '")'; }
  x.addEventListener('click', fermerBoutique);
  el.appendChild(x);
  const zone = mk('div', 'mq-fz');
  zone.style.color = I.texte || '#E9E6DD';
  if(L.police) zone.style.fontFamily = '"' + L.police + '", system-ui, sans-serif';
  if(I.image) daCadrePose(zone, I.image, I.coins || 24, { padding: 14 });
  else zone.style.background = mRgba(I.fond || '#10131B', I.opacite == null ? 0.92 : I.opacite);
  el.appendChild(zone);
  function posZone(){
    const W = scene.clientWidth, H = scene.clientHeight;
    if(!W || !H || zone.style.display === 'none') return;
    zone.style.width = Math.min((I.largeur || 0.62) * W, 520, W - 24) + 'px';
    const p = mqFondZone(W, H, zone.offsetWidth, zone.offsetHeight, I.x == null ? 0.5 : I.x, I.y == null ? 0.84 : I.y);
    zone.style.left = p.x + 'px';
    zone.style.top = p.y + 'px';
  }
  function place(){
    const W = scene.clientWidth, H = scene.clientHeight, d = v.fondDim && v.fondDim.src === fond ? v.fondDim : {};
    if(!W || !H) return;
    objets.forEach(function(q){
      const p = mqFondPlace(W, H, d.w, d.h, q.x, q.y, q.t);
      q.px = p.x; q.py = p.y; q.pt = p.taille;
      q.c.style.left = p.x + 'px'; q.c.style.top = p.y + 'px';
      q.c.style.width = p.taille + 'px'; q.c.style.height = p.taille + 'px';
    });
    posZone();
  }
  function remplis(){
    zone.textContent = '';
    const q = objets.filter(function(n){ return n.i === v.fsel; })[0];
    if(!q && !v.dit){ zone.style.display = 'none'; return; }
    zone.style.display = '';
    if(q){
      zone.appendChild(mk('div', 'mq-nom', q.o.nom));
      if(q.o.info) zone.appendChild(mk('div', 'mq-fz-texte', q.o.info));
      const bas = mk('div', 'mq-fz-bas');
      bas.appendChild(mk('div', 'mq-fz-prix', mTexteEtiquette(b, q.o.m, q.o.p)));
      const achat = mBouton(bas, q.o.reste ? (q.o.p ? 'Acheter' : 'Prendre') : '\xC9puis\xE9', function(){ mAcheter(b, q.l, zone); }, false, !q.o.reste);
      achat.setAttribute('data-fond-acheter', '');
      if(vi.acheterImage){ daCadrePose(achat, vi.acheterImage, vi.acheterCoins || 12, {}); achat.style.padding = '0 6px'; }
      if(b.marchandage && b.marchandage.actif && q.o.p > 0 && q.o.reste && vars[mCle('neg', b, q.l.itemId)] == null){
        mBouton(bas, 'Marchander', function(){ mMarchander(b, q.l, q.o.it); }, true);
      }
      zone.appendChild(bas);
    }
    if(v.dit) zone.appendChild(mk('div', 'mq-bulle', v.dit));
    posZone();
  }
  function marque(){ objets.forEach(function(q){ q.c.classList.toggle('on', q.i === v.fsel); }); }
  function choisir(i){
    if(i === v.fsel && (i != null || !v.dit)) return;
    v.fsel = i;
    v.dit = '';
    marque();
    remplis();
  }
  function sous(e){
    const r = scene.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top;
    let meilleur = null, dist = Infinity;
    objets.forEach(function(q){
      const dx = Math.abs(px - q.px), dy = Math.abs(py - q.py), m = q.pt / 2;
      if(dx > m || dy > m) return;
      const n = dx * dx + dy * dy;
      if(n < dist){ dist = n; meilleur = q; }
    });
    return meilleur;
  }
  /*  \xC0 la souris, la zone suit le survol et part quand on quitte l'objet ;
      un clic sur l'objet la garde, pour pouvoir aller jusqu'\xE0 Acheter.
      Au doigt, elle reste apr\xE8s le lever et se referme en touchant ailleurs. */
  let presse = false;
  function annule(){ if(v.fmin){ clearTimeout(v.fmin); v.fmin = 0; } }
  function plusTard(){
    if(v.fpin || v.fsel == null || v.fmin) return;
    v.fmin = setTimeout(function(){ v.fmin = 0; if(!v.fpin && boutiqueV === v) choisir(null); }, 220);
  }
  scene.addEventListener('pointerdown', function(e){
    presse = true; annule();
    const q = sous(e);
    v.fpin = e.pointerType === 'mouse' && !!q;
    choisir(q ? q.i : null);
  });
  scene.addEventListener('pointermove', function(e){
    const q = sous(e);
    if(e.pointerType === 'mouse' && !presse){
      if(v.fpin) return;
      if(q){ annule(); choisir(q.i); } else plusTard();
      return;
    }
    if(e.pointerType === 'mouse') v.fpin = !!q;
    if(q) choisir(q.i); else if(presse) choisir(null);
  });
  scene.addEventListener('pointerup', function(){ presse = false; });
  scene.addEventListener('pointercancel', function(){ presse = false; });
  scene.addEventListener('pointerleave', function(e){ if(e.pointerType === 'mouse'){ presse = false; plusTard(); } });
  zone.addEventListener('pointerenter', function(e){ if(e.pointerType === 'mouse') annule(); });
  zone.addEventListener('pointerleave', function(e){ if(e.pointerType === 'mouse') plusTard(); });
  objets.forEach(function(q){ q.c.addEventListener('click', function(){ choisir(q.i); }); });
  if(v.fsel != null && !objets.some(function(q){ return q.i === v.fsel; })) v.fsel = null;
  place();
  marque();
  remplis();
  if(fond && !(v.fondDim && v.fondDim.src === fond)){
    scene.classList.add('att');
    const im = new Image();
    im.onload = function(){ v.fondDim = { src: fond, w: im.naturalWidth, h: im.naturalHeight }; place(); scene.classList.remove('att'); };
    im.onerror = function(){ scene.classList.remove('att'); };
    im.src = fond;
  }
  if(window.ResizeObserver){ v.fondRO = new ResizeObserver(place); v.fondRO.observe(scene); }
}


