alphabet: ['digits', 'letters', 'hex', 'custom'].indexOf(s.alphabet) >= 0 ? s.alphabet : 'digits',
customAlphabet: puzStr(s.customAlphabet).slice(0, 60),
length: Math.round(puzNum(s.length, 4, 1, 12)),
