/*  Une grille plus large que le panneau rognait sa derniere colonne sur
    un telephone. Une fois le panneau pose, on mesure la place et on ne
    garde que les colonnes qui tiennent (jamais plus que l'auteur n'en veut). */
function pnlColonnes(box, cfg){
  const g = box.querySelector('.pnl-grid');
  if(!g) return;
  const cs = getComputedStyle(box);
  const dispo = box.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
  if(!(dispo > 0)) return;
  const gap = parseFloat(getComputedStyle(g).columnGap) || 10;
  const n = Math.max(1, Math.min(cfg.columns, Math.floor((dispo + gap) / (cfg.cell + gap))));
  g.style.gridTemplateColumns = 'repeat(' + n + ', ' + cfg.cell + 'px)';
}
function hudItemDef(id, defs){ return (defs || []).filter(function(i){ return i.id === id; })[0] || null; }
function hudInvRow(id, cfg, defs){
  const it = hudItemDef(id, defs);
  const n = uiNumberOf(inventory[id]);
  const row = mk('div', 'pnl-row');
  row.setAttribute('data-inv-item', id);
  if(it && it.image){
    const im = document.createElement('img');
    im.src = it.image; im.alt = '';
    im.className = 'pnl-ico';
    row.appendChild(im);
  }
  const txt = mk('div', 'pnl-text');
  if(cfg.showName !== false) txt.appendChild(mk('span', 'pnl-name', (it ? it.name : id) + (n > 1 ? ' \xD7' + n : '')));
  if(cfg.showDescription && it && it.description) txt.appendChild(mk('span', 'pnl-desc', it.description));
  row.appendChild(txt);
  return row;
}
function hudInvCell(id, cfg, defs){
  const it = hudItemDef(id, defs);
  const n = uiNumberOf(inventory[id]);
  const cell = mk('div', 'pnl-cell');
  cell.setAttribute('data-inv-item', id);
  cell.style.width = cfg.cell + 'px';
  cell.style.height = cfg.cell + 'px';
  cell.title = (it ? it.name : id) + (it && it.description ? ' \u2014 ' + it.description : '');
  const pic = mk('span', 'hud-in');
  pic.appendChild(hudItemNode(id, cfg.cell, ''));
  cell.appendChild(pic);
  if(n > 1) cell.appendChild(mk('span', 'hud-count', String(n)));
  if(cfg.showName !== false) cell.appendChild(mk('span', 'pnl-cap', (it ? it.name : id)));
  return cell;
}
/*  La combinaison d'objets : le module partage prepare les actions, le
    moteur d'actions habituel les applique, puis le sac se redessine. */
let comboCache = null, comboAnnonce = null;
function comboDuJeu(){
  if(!comboCache) comboCache = normalizeCombinations(GAME.combinations);
  return comboCache;
}
function comboJouer(a, b){
  const r = comboPrepare(comboDuJeu(), inventory, vars, a, b);
  if(!r.ok) return r;
  const eff = runActions(r.actions);
  const textes = eff.filter(function(e){ return e.kind === 'text'; }).map(function(e){ return e.text; });
  const nav = pickNavigate(eff, null);
  const dlg = eff.filter(function(e){ return e.kind === 'dialogue'; })[0];
  /*  Une recette peut aussi emmener ailleurs : on ferme le sac d'abord. */
  if(nav || dlg){
    closeInv();
    if(nav) loadScene(nav);
    if(dlg) openDialogue(dlg.dialogId);
    if(r.texte || textes.length) showModal([r.texte].concat(textes).filter(Boolean).join(' '));
    return r;
  }
  comboAnnonce = { texte: [r.texte].concat(textes).filter(Boolean).join(' ') || '', item: r.recette.result };
  closeInv();
  openInv();
  return r;
}
