    const sid = GAME.scenes.some(function(s){ return s.id === TEST_START.sceneId; }) ? TEST_START.sceneId : startSceneId();
    inventory = Object.assign({}, TEST_START.inventory || {});
    vars = Object.assign(initialVars(GAME.variables), TEST_START.vars || {});
    const sc0 = GAME.scenes.filter(function(s){ return s.id === sid; })[0];
    if(sc0 && sc0.parentId) vars[sousCle(sc0.parentId)] = sid;
